package hoc.unam

import java.io.IOException

class App {
    val greeting: String
        get() {
            return "Hello World!"
        }
}


fun main() {
    //val graphFilePath: String = "/home/mexidis/development/mintree/files/input.txt"
    val graphFilePath = "files/input.txt"
    try {
        val reader = FileReaderToGraph(graphFilePath)

        val myGraph = reader.createGraphFromFile()


        val distance_a_b = myGraph.getDistance("a", "b")
        println(distance_a_b)

        val distance_f_g = myGraph.getDistance("f", "g")
        println(distance_f_g) // Debería ser 11.0

        myGraph.printGraphMatrix(MatrixType.ADJACENCY)
        myGraph.completeGraph()
        val shortestPaths = myGraph.getAdjMatShortestPaths()
        // Imprimir la matriz de resultados
        myGraph.printGraphMatrix(MatrixType.SHORTEST_PATHS)


        myGraph.printGraphMatrix(MatrixType.COMPLETED)


        val kNodes = 4 // Queremos un MST que conecte 4 nodos (3 aristas)

        println("\n--- Ejecutando el Algoritmo de Prim (K=$kNodes MST) ---")
        val totalMstCost = myGraph.primsAlgorithm(kNodes)
        println("-------------------------------------------------------")
        println("Costo Total del MST de $kNodes nodos: ${"%.2f".format(totalMstCost)}")
        println("-------------------------------------------------------")
        //myGraph.printMatrix()

    } catch (e: IOException) {
        // Este bloque se ejecutará si el archivo no se encuentra
        System.err.println("Error al leer el archivo: ${e.message}")
    } catch (e: Exception) {
        // Para cualquier otro error inesperado
        System.err.println("Ocurrió un error inesperado: ${e.message}")
    }
}

